45	    /**
46	     * Derive the owner's age band from the supplied birthDate, evaluated against the owner's
47	     * registrationDate: 'MINOR' when under 18, 'ADULT' when 18 to 64 inclusive, and 'SENIOR' when
48	     * 65 or older. Returns null when no birthDate was supplied (or no registrationDate is available)
49	     * so owners without a birth date serialize cleanly.
50	     */
51	    default String ageBand(Owner owner) {
52	        java.time.LocalDate birthDate = owner.getBirthDate();
53	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
54	        if (birthDate == null || registrationDate == null) {
55	            return null;
56	        }
57	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
58	        if (age < 18) {
59	            return "MINOR";
60	        }
61	        if (age < 65) {
62	            return "ADULT";
63	        }
64	        return "SENIOR";
65	    }
