69	     * formatting {@code telephoneDisplay} (matching the codes validated on create). The longest
70	     * matching code wins so a shorter code that is a prefix of another cannot mask it.
71	     */
72	    java.util.Set<String> KNOWN_COUNTRY_CODES = java.util.Set.of("1", "61");
